import sys
import heapq

def dijkstra(n, graph, start):
    dist = [float('inf')] * (n + 1)
    dist[start] = 0
    pq = [(0, start)]
    while pq:
        d, u = heapq.heappop(pq)
        if d > dist[u]:
            continue
        for v, w in graph[u]:
            if dist[u] + w < dist[v]:
                dist[v] = dist[u] + w
                heapq.heappush(pq, (dist[v], v))
    return dist

def floyd_warshall(n, graph):
    dist = [[float('inf')] * (n + 1) for _ in range(n + 1)]
    for u in range(1, n + 1):
        dist[u][u] = 0
    for u in range(1, n + 1):
        for v, w in graph[u]:
            dist[u][v] = w
    for k in range(1, n + 1):
        for i in range(1, n + 1):
            for j in range(1, n + 1):
                if dist[i][k] + dist[k][j] < dist[i][j]:
                    dist[i][j] = dist[i][k] + dist[k][j]
    return dist

def count_important_roads(n, m, edges):
    graph = [[] for _ in range(n + 1)]
    for u, v, w in edges:
        graph[u].append((v, w))
        graph[v].append((u, w))

    dist = floyd_warshall(n, graph)

    important_roads = set()
    for s in range(1, n):
        for t in range(s + 1, n + 1):
            if dist[s][t] == float('inf'):
                continue
            visited = [False] * (n + 1)
            queue = [s]
            while queue:
                u = queue.pop(0)
                if visited[u]:
                    continue
                visited[u] = True
                for v, w in graph[u]:
                    if dist[s][u] + w == dist[s][v]:
                        important_roads.add((min(u, v), max(u, v)))
                        queue.append(v)

    result = []
    for s in range(1, n):
        for t in range(s + 1, n + 1):
            if dist[s][t] == float('inf'):
                result.append(0)
            else:
                count = sum(1 for u, v in important_roads if (u, v) in edges or (v, u) in edges)
                result.append(count)

    return result

